// Store custom donation amount in cart item data
add_filter('woocommerce_add_cart_item_data', 'lexington_alarm_add_donation_cart_data', 10, 3);
function lexington_alarm_add_donation_cart_data($cart_item_data, $product_id, $variation_id) {
    if (isset($_POST['custom_donation_amount']) && !empty($_POST['custom_donation_amount'])) {
        $quantity = intval($_POST['custom_donation_amount']);
        if ($quantity >= 1) {
            $custom_amount = $quantity * 5; // Calculate total based on $5 units
            $cart_item_data['custom_donation_amount'] = $custom_amount;
            $cart_item_data['custom_donation_quantity'] = $quantity;
            $cart_item_data['unique_key'] = md5(microtime().rand());
        }
    }
    return $cart_item_data;
}

// Update the price in cart for custom donations
add_action('woocommerce_before_calculate_totals', 'lexington_alarm_update_donation_price', 99, 1);
function lexington_alarm_update_donation_price($cart) {
    // Skip if in admin and not doing AJAX
    if (is_admin() && !defined('DOING_AJAX')) {
        return;
    }
    
    // Prevent multiple calls
    if (did_action('woocommerce_before_calculate_totals') >= 2) {
        return;
    }
    
    foreach ($cart->get_cart() as $cart_item_key => $cart_item) {
        // Check if custom donation amount exists
        if (isset($cart_item['custom_donation_amount']) && $cart_item['custom_donation_amount'] > 0) {
            // Get the custom amount
            $custom_price = floatval($cart_item['custom_donation_amount']);
            
            // Set the new price
            $cart_item['data']->set_price($custom_price);
        }
    }
}

