        <script>
        jQuery(document).ready(function($) {
            
            // =============================================
            // CATEGORY SWITCHER
            // =============================================
            $('.category-switcher').on('change', function() {
                var postId = $(this).data('post-id');
                var newCategory = $(this).val();
                var $select = $(this);
                
                if (newCategory === 'feature') {
                    if (!confirm('This will make this post the featured story and remove featured status from any other post. Continue?')) {
                        $select.val($select.data('previous'));
                        return;
                    }
                }
                
                $select.data('previous', $select.val());
                $select.prop('disabled', true);
                
                $.ajax({
                    url: '<?php echo admin_url('admin-ajax.php'); ?>',
                    type: 'POST',
                    data: {
                        action: 'la_change_category',
                        post_id: postId,
                        category: newCategory,
                        nonce: '<?php echo wp_create_nonce('la_category_change'); ?>'
                    },
                    success: function(response) {
                        location.reload();
                    },
                    error: function() {
                        alert('Error changing category. Please try again.');
                        $select.prop('disabled', false);
                    }
                });
            });
            
            $('.category-switcher').each(function() {
                $(this).data('previous', $(this).val());
            });
            
            // =============================================
            // INLINE FEATURED TEXT EDITING
            // =============================================
            $('.edit-excerpt-link').on('click', function(e) {
                e.preventDefault();
                var $row = $(this).closest('.excerpt-row');
                $row.find('.excerpt-preview-mode').hide();
                $row.find('.excerpt-edit-mode').slideDown(200);
                $row.find('.excerpt-textarea').focus();
            });
            
            $('.cancel-excerpt-btn').on('click', function() {
                var $row = $(this).closest('.excerpt-row');
                $row.find('.excerpt-edit-mode').slideUp(200, function() {
                    $row.find('.excerpt-preview-mode').show();
                });
                $row.find('.excerpt-status').text('');
            });
            
            $('.save-excerpt-btn').on('click', function() {
                var $btn = $(this);
                var $row = $btn.closest('.excerpt-row');
                var postId = $row.data('post-id');
                var newExcerpt = $row.find('.excerpt-textarea').val();
                var $status = $row.find('.excerpt-status');
                
                // Disable button and show saving state
                $btn.prop('disabled', true).text('SAVING...');
                $status.text('').css('color', '#666');
                
                $.ajax({
                    url: '<?php echo admin_url('admin-ajax.php'); ?>',
                    type: 'POST',
                    data: {
                        action: 'la_update_excerpt',
                        post_id: postId,
                        excerpt: newExcerpt,
                        nonce: '<?php echo wp_create_nonce('la_excerpt_update'); ?>'
                    },
                    success: function(response) {
                        if (response.success) {
                            // Update the preview text
                            var $previewText = $row.find('.excerpt-preview-text');
                            if (response.data.excerpt) {
                                var previewText = response.data.preview || response.data.excerpt;
                                $previewText.html('"' + $('<div>').text(previewText).html() + '"');
                            } else {
                                $previewText.html('<em style="color: #999;">(auto-generated from content)</em>');
                            }
                            
                            // Show success and close editor
                            $status.text('✓ Saved!').css('color', '#28a745');
                            
                            setTimeout(function() {
                                $row.find('.excerpt-edit-mode').slideUp(200, function() {
                                    $row.find('.excerpt-preview-mode').show();
                                });
                            }, 1000);
                        } else {
                            $status.text('Error: ' + (response.data || 'Unknown error')).css('color', '#dc3545');
                        }
                    },
                    error: function() {
                        $status.text('Connection error. Please try again.').css('color', '#dc3545');
                    },
                    complete: function() {
                        $btn.prop('disabled', false).text('SAVE');
                    }
                });
            });
            
            // Keyboard shortcuts for excerpt editing
            $('.excerpt-textarea').on('keydown', function(e) {
                // Ctrl+Enter to save
                if (e.ctrlKey && e.keyCode === 13) {
                    $(this).closest('.excerpt-edit-mode').find('.save-excerpt-btn').click();
                }
                // Escape to cancel
                if (e.keyCode === 27) {
                    $(this).closest('.excerpt-edit-mode').find('.cancel-excerpt-btn').click();
                }
            });
            
            // =============================================
            // IMAGE PREVIEW
            // =============================================
            var imageInput = document.getElementById('post_image');
            if (imageInput) {
                imageInput.addEventListener('change', function(e) {
                    var file = e.target.files[0];
                    if (file && file.type.startsWith('image/')) {
                        var reader = new FileReader();
                        reader.onload = function(e) {
                            document.getElementById('image-preview').innerHTML = 
                                '<img src="' + e.target.result + '" style="max-width: 300px; height: auto;">';
                        };
                        reader.readAsDataURL(file);
                    }
                });
            }
            
            // =============================================
            // AUTO-BACKUP FEATURE
            // =============================================
            if ($('#la-news-form').length === 0) return;
            
            var STORAGE_KEY = 'la_news_draft';
            var AUTOSAVE_INTERVAL = 2000;        // Save every 2 seconds
            var NOTIFICATION_INTERVAL = 15000;   // Show notification every 15 seconds
            var lastNotificationTime = 0;
            
            var fieldSelectors = {
                post_title: '#post_title',
                post_excerpt: '#post_excerpt',
                post_content: '#post_content'
            };
            
            // Save draft to localStorage
            function saveDraft() {
                var draft = {
                    post_title: $(fieldSelectors.post_title).val(),
                    post_excerpt: $(fieldSelectors.post_excerpt).val(),
                    post_content: $(fieldSelectors.post_content).val(),
                    featured_story: $('input[name="featured_story"]').is(':checked'),
                    saved_at: new Date().toISOString()
                };
                
                if (draft.post_title || draft.post_content) {
                    localStorage.setItem(STORAGE_KEY, JSON.stringify(draft));
                    
                    // Only show notification every 15 seconds
                    var now = Date.now();
                    if (now - lastNotificationTime >= NOTIFICATION_INTERVAL) {
                        showSaveIndicator();
                        lastNotificationTime = now;
                    }
                }
            }
            
            // Show save indicator
            function showSaveIndicator() {
                $('#autosave-indicator').remove();
                $('#la-news-form').before(
                    '<div id="autosave-indicator" style="background: #d4edda; color: #155724; padding: 8px 15px; margin-bottom: 10px; border-radius: 4px; font-size: 0.9em;">' +
                    '✓ Draft auto-saved at ' + new Date().toLocaleTimeString() +
                    '</div>'
                );
                setTimeout(function() {
                    $('#autosave-indicator').fadeOut();
                }, 3000);
            }
            
            // Check for saved draft
            function checkForDraft() {
                var saved = localStorage.getItem(STORAGE_KEY);
                
                if (saved) {
                    var draft = JSON.parse(saved);
                    var savedDate = new Date(draft.saved_at);
                    var timeAgo = getTimeAgo(savedDate);
                    
                    var recoveryHtml = 
                        '<div id="draft-recovery" style="background: #fff3cd; border: 2px solid #ffc107; color: #856404; padding: 20px; margin-bottom: 20px;">' +
                        '<strong>📝 Unsaved Draft Found!</strong><br>' +
                        'You have a draft from ' + timeAgo + ' (' + savedDate.toLocaleString() + ')<br><br>' +
                        '<strong>Title:</strong> ' + escapeHtml(draft.post_title || '(no title)') + '<br>' +
                        '<strong>Content preview:</strong> ' + escapeHtml((draft.post_content || '').substring(0, 100)) + '...<br><br>' +
                        '<button type="button" id="restore-draft" style="background: #28a745; color: white; padding: 10px 20px; border: none; font-weight: bold; cursor: pointer; margin-right: 10px;">RESTORE DRAFT</button>' +
                        '<button type="button" id="discard-draft" style="background: #dc3545; color: white; padding: 10px 20px; border: none; font-weight: bold; cursor: pointer;">DISCARD</button>' +
                        '</div>';
                    
                    $('#la-news-form').before(recoveryHtml);
                    
                    $('#restore-draft').on('click', function() {
                        $(fieldSelectors.post_title).val(draft.post_title || '');
                        $(fieldSelectors.post_excerpt).val(draft.post_excerpt || '');
                        $(fieldSelectors.post_content).val(draft.post_content || '');
                        $('input[name="featured_story"]').prop('checked', draft.featured_story);
                        
                        $('#draft-recovery').html(
                            '<div style="color: #155724; background: #d4edda; padding: 15px; border: 2px solid #28a745;">' +
                            '<strong>✓ Draft restored!</strong> Your content has been loaded into the form.' +
                            '</div>'
                        );
                        
                        setTimeout(function() {
                            $('#draft-recovery').fadeOut();
                        }, 3000);
                    });
                    
                    $('#discard-draft').on('click', function() {
                        if (confirm('Are you sure you want to discard this draft? This cannot be undone.')) {
                            localStorage.removeItem(STORAGE_KEY);
                            $('#draft-recovery').fadeOut();
                        }
                    });
                }
            }
            
            // Calculate time ago
            function getTimeAgo(date) {
                var seconds = Math.floor((new Date() - date) / 1000);
                if (seconds < 60) return 'just now';
                if (seconds < 3600) return Math.floor(seconds / 60) + ' minutes ago';
                if (seconds < 86400) return Math.floor(seconds / 3600) + ' hours ago';
                return Math.floor(seconds / 86400) + ' days ago';
            }
            
            // Escape HTML
            function escapeHtml(text) {
                if (!text) return '';
                var div = document.createElement('div');
                div.textContent = text;
                return div.innerHTML;
            }
            
            // Clear draft on successful submission
            function clearDraftOnSubmit() {
                if (window.location.search.indexOf('news_submitted=success') > -1) {
                    localStorage.removeItem(STORAGE_KEY);
                }
            }
            
            // Add manual save button
            function addManualSaveButton() {
                var saveBtn = '<button type="button" id="manual-save-draft" style="background: #6c757d; color: white; padding: 15px 30px; border: none; font-size: 1.1em; font-weight: bold; cursor: pointer; margin-left: 10px;">SAVE DRAFT</button>';
                $('#la-news-form button[type="submit"]').after(saveBtn);
                
                $('#manual-save-draft').on('click', function() {
                    saveDraft();
                    alert('Draft saved! Your content is backed up locally.');
                });
            }
            
            // Initialize auto-backup
            clearDraftOnSubmit();
            checkForDraft();
            addManualSaveButton();
            
            // Auto-save on typing
            var typingTimer;
            $('#post_title, #post_excerpt, #post_content').on('keyup', function() {
                clearTimeout(typingTimer);
                typingTimer = setTimeout(saveDraft, 2000);
            });
            
            $('input[name="featured_story"]').on('change', saveDraft);
            setInterval(saveDraft, AUTOSAVE_INTERVAL);
            
            $(window).on('beforeunload', function() {
                saveDraft();
            });
            
        });
        </script>
        <?php endif; ?>
    </div>
    <?php
    return ob_get_clean();
}

// Handle bulk delete
function la_handle_bulk_delete() {
    if (isset($_POST['bulk_delete']) && isset($_POST['la_bulk_delete_nonce'])) {
        if (!wp_verify_nonce($_POST['la_bulk_delete_nonce'], 'la_bulk_delete')) {
            return;
        }
        
        if (!current_user_can('delete_posts')) {
            return;
        }
        
        if (isset($_POST['delete_posts']) && is_array($_POST['delete_posts'])) {
            foreach ($_POST['delete_posts'] as $post_id) {
                $post_id = intval($post_id);
                if ($post_id > 0) {
                    wp_trash_post($post_id);
                }
            }
            
            wp_redirect(add_query_arg('bulk_deleted', count($_POST['delete_posts']), get_permalink()));
            exit;
        }
    }
}
add_action('init', 'la_handle_bulk_delete');

// Handle news submission
function la_handle_news_submission() {
    // Only process if our nonce is present
    if (!isset($_POST['la_news_nonce'])) {
        return;
    }
    
    // Verify nonce
    if (!wp_verify_nonce($_POST['la_news_nonce'], 'la_submit_news')) {
        return;
    }
    
    // Must be logged in
    if (!is_user_logged_in()) {
        return;
    }
    
    // Must have post_title
    if (!isset($_POST['post_title']) || empty($_POST['post_title'])) {
        return;
    }
    
    $blog_cat = get_category_by_slug('blog');
    $categories = array();
    
    if ($blog_cat) {
        $categories[] = $blog_cat->term_id;
    }
    
    // Get byline - save it before creating post
    $byline_value = '';
    if (isset($_POST['post_byline']) && !empty(trim($_POST['post_byline']))) {
        $byline_value = sanitize_text_field($_POST['post_byline']);
    }
    
    // Determine post status based on user capability
    $post_status = current_user_can('publish_posts') ? 'publish' : 'pending';
    
    $post_data = array(
        'post_title' => sanitize_text_field($_POST['post_title']),
        'post_content' => wpautop(wp_kses_post($_POST['post_content'])),
        'post_excerpt' => isset($_POST['post_excerpt']) ? wp_kses_post($_POST['post_excerpt']) : '',
        'post_status' => $post_status,
        'post_author' => get_current_user_id(),
        'post_type' => 'post',
        'post_category' => $categories
    );
    
    $post_id = wp_insert_post($post_data);
    
    if ($post_id && !is_wp_error($post_id)) {
        
        // Save byline
        if (!empty($byline_value)) {
            update_post_meta($post_id, 'la_byline', $byline_value);
        }
        
        // Handle featured story
        if (isset($_POST['featured_story']) && $_POST['featured_story'] == '1') {
            $featured_cat = get_category_by_slug('feature');
            if ($featured_cat) {
                wp_set_post_categories($post_id, array($featured_cat->term_id), true);
            }
        }
        
        // Handle image upload
        if (!empty($_FILES['post_image']['name'])) {
            require_once(ABSPATH . 'wp-admin/includes/file.php');
            require_once(ABSPATH . 'wp-admin/includes/image.php');
            require_once(ABSPATH . 'wp-admin/includes/media.php');
            
            $attachment_id = media_handle_upload('post_image', $post_id);
            if (!is_wp_error($attachment_id)) {
                set_post_thumbnail($post_id, $attachment_id);
            }
        }
        
        // Send notification to news team
        la_notify_news_team($post_id, $post_status, wp_get_current_user()->display_name);

        $redirect_url = add_query_arg('news_submitted', 'success', get_permalink());
        wp_redirect($redirect_url);
        exit;
    }
}
add_action('init', 'la_handle_news_submission');

