// Get custom byline (use in theme templates)
function la_get_byline($post_id = null) {
    if (!$post_id) {
        $post_id = get_the_ID();
    }
    $byline = get_post_meta($post_id, 'la_byline', true);
    
    if (!empty($byline)) {
        return $byline;
    }
    
    // Fallback to post author name
    $post = get_post($post_id);
    if ($post) {
        $author = get_userdata($post->post_author);
        return $author ? $author->display_name : '';
    }
    return '';
}

// Filter the author display name to show custom byline
function la_filter_author_name($author_name) {
    $post_id = get_the_ID();
    if ($post_id) {
        $byline = get_post_meta($post_id, 'la_byline', true);
        if (!empty($byline)) {
            return $byline;
        }
    }
    return $author_name;
