add_action('woocommerce_before_checkout_form', 'lexington_alarm_checkout_pickup_notice', 5);
function lexington_alarm_checkout_pickup_notice() {
    $has_local_only = false;
    $has_shipped = false;
    $has_virtual_only = false;
    $all_virtual = true;
    $local_only_items = array();
    
    foreach (WC()->cart->get_cart() as $cart_item) {
        $product = $cart_item['data'];
        $shipping_class = $product->get_shipping_class();
        
        // Check if product is virtual (donations, digital goods)
        if ($product->is_virtual()) {
            $has_virtual_only = true;
            continue; // Skip to next item - virtual products need no shipping
        }
        
        // If we get here, product is NOT virtual
        $all_virtual = false;
        
        if ($shipping_class === 'local-pickup-only' || $shipping_class === 'local_pickup_only') {
            $has_local_only = true;
            $local_only_items[] = $product->get_name();
        } elseif ($shipping_class === 'ships-nationwide' || $shipping_class === 'ships_nationwide' || $shipping_class === 'ships-only') {
            $has_shipped = true;
        }
    }
    
    // SCENARIO 1: Cart contains ONLY virtual products (donations)
    if ($all_virtual && $has_virtual_only) {
        echo '<div class="woocommerce-info" style="background: #044f9d; color: #ffffff; border: 3px solid #c3202e; padding: 20px; margin-bottom: 30px; font-size: 16px; line-height: 1.6;">';
        echo '<strong style="font-size: 18px; display: block; margin-bottom: 10px;">💙 THANK YOU FOR YOUR DONATION!</strong>';
        echo '<p style="margin: 10px 0;">No shipping address is needed for donations.</p>';
        echo '<p style="margin: 10px 0;">Just enter your email and payment information below.</p>';
        echo '</div>';
        return;
    }
    
    // SCENARIO 2: Cart has ONLY local pickup items (no shipping address needed)
    if ($has_local_only && !$has_shipped) {
        $item_list = implode(', ', $local_only_items);
        echo '<div class="woocommerce-info" style="background: #044f9d; color: #ffffff; border: 3px solid #c3202e; padding: 20px; margin-bottom: 30px; font-size: 16px; line-height: 1.6;">';
        echo '<strong style="font-size: 18px; display: block; margin-bottom: 10px;">⚠️ LOCAL PICKUP ONLY - NO SHIPPING ADDRESS NEEDED</strong>';
        echo '<p style="margin: 10px 0;">Your cart contains items available for <strong>LOCAL PICKUP ONLY</strong> in Lexington, MA:</p>';
        echo '<p style="margin: 10px 0; padding-left: 20px;"><strong>' . esc_html($item_list) . '</strong></p>';
        echo '<p style="margin: 10px 0;"><strong>📍 Pickup Location:</strong><br>';
        echo 'Lexington Visitor Center<br>';
        echo '1875 Massachusetts Avenue<br>';
        echo 'Lexington, MA 02420</p>';
        echo '<p style="margin: 10px 0;"><strong>📧 We will email you when your order is ready for pickup.</strong></p>';
        echo '<hr style="border-color: rgba(255,255,255,0.3); margin: 15px 0;">';
        echo '<p style="margin: 10px 0; font-size: 14px;"><em>If you need items shipped to your address, please visit our <a href="' . home_url('/shop') . '" style="color: #ffffff; text-decoration: underline;">shop page</a> and select items from the "SHIPPED ITEMS" section.</em></p>';
        echo '</div>';
    }
    // SCENARIO 3: Cart has mixed items (pickup + shipped)
    elseif ($has_local_only && $has_shipped) {
        echo '<div class="woocommerce-info" style="background: #fffacd; border-left: 4px solid #c3202e; padding: 15px; margin-bottom: 20px;">';
        echo '<strong>⚠️ Mixed Order: Local Pickup + Shipped Items</strong>';
        echo '<p style="margin: 10px 0;">Your cart contains both local pickup and shipped items. You will need to:</p>';
        echo '<ul style="margin: 10px 0 10px 20px;">';
        echo '<li><strong>Pick up these items</strong> in Lexington, MA: ' . esc_html(implode(', ', $local_only_items)) . '</li>';
        echo '<li><strong>Provide a shipping address</strong> below for your shipped items</li>';
        echo '</ul>';
        echo '</div>';
    }
}

