/**
 * Customize Admin Order Email Subject Line
 * Adds [SHIPPING], [LOCAL PICKUP], [MERCH], or [DONATION] prefix to order notification emails
 * Version: 1.2 - FIXED LOCAL PICKUP DETECTION
 * 
 * INSTALLATION:
 * 1. Go to WordPress Admin > WPCode > Snippets
 * 2. Find "Admin Email Subject - Shipping/Pickup Labels"
 * 3. Replace the code with this version
 * 4. Save and test
 */
add_filter('woocommerce_email_subject_new_order', 'lexington_customize_admin_order_subject', 10, 2);
function lexington_customize_admin_order_subject($subject, $order) {
    if (!$order) return $subject;
    
    $order_type_label = '';
    $is_donation = false;
    $is_printful = false;
    $has_local_pickup = false;
    $has_shipping = false;
    
    // First, check if this is a donation order
    foreach ($order->get_items() as $item) {
        $product = $item->get_product();
        if (!$product) continue;
        
        // Check by SKU first (most reliable for variable products)
        $sku = $product->get_sku();
        if ($sku === 'Lex-Donation') {
            $is_donation = true;
            break;
        }
        
        // Also check product name as fallback
        $product_name = strtolower($product->get_name());
        if (strpos($product_name, 'donate') !== false || strpos($product_name, 'donation') !== false) {
            $is_donation = true;
            break;
        }
    }
    
    // If it's a donation, label it and exit
    if ($is_donation) {
        $subject = preg_replace('/^\[.*?\]\s*/', '', $subject);
        $subject = '[DONATION] ' . $subject;
        return $subject;
    }
    
    // Check if this is a Printful order
    foreach ($order->get_items() as $item) {
        $product = $item->get_product();
        if (!$product) continue;
        
        // Check product category for "printful"
        $terms = get_the_terms($product->get_id(), 'product_cat');
        if ($terms && !is_wp_error($terms)) {
            foreach ($terms as $term) {
                $cat_slug = strtolower($term->slug);
                $cat_name = strtolower($term->name);
                
                if (strpos($cat_slug, 'printful') !== false || strpos($cat_name, 'printful') !== false) {
                    $is_printful = true;
                    break 2;
                }
            }
        }
        
        // Also check shipping class for "printful"
        $shipping_class = $product->get_shipping_class();
        if ($shipping_class && strpos(strtolower($shipping_class), 'printful') !== false) {
            $is_printful = true;
            break;
        }
    }
    
    // If it's a Printful order, label it as MERCH and exit
    if ($is_printful) {
        $subject = preg_replace('/^\[.*?\]\s*/', '', $subject);
        $subject = '[MERCH] ' . $subject;
        return $subject;
    }
    
    // ===== FIX STARTS HERE =====
    // Check PRODUCT SHIPPING CLASSES first (more reliable than order shipping methods)
    foreach ($order->get_items() as $item) {
        $product = $item->get_product();
        if (!$product) continue;
        
        // Get the shipping class for this product
        $shipping_class = $product->get_shipping_class();
        
        if ($shipping_class) {
            $shipping_class_lower = strtolower($shipping_class);
            
            // Check if shipping class indicates local pickup
            if (strpos($shipping_class_lower, 'local') !== false || 
                strpos($shipping_class_lower, 'pickup') !== false) {
                $has_local_pickup = true;
            } else {
                // If it has a shipping class but not local pickup, assume it ships
                $has_shipping = true;
            }
        }
    }
    
    // Also check order shipping methods as secondary check
    $shipping_methods = $order->get_shipping_methods();
    foreach ($shipping_methods as $shipping_method) {
        $method_id = $shipping_method->get_method_id();
        $method_title = strtolower($shipping_method->get_method_title());
        
        if (strpos($method_id, 'local_pickup') !== false || 
            strpos($method_title, 'local') !== false || 
            strpos($method_title, 'pickup') !== false) {
            $has_local_pickup = true;
        } else {
            $has_shipping = true;
        }
    }
    
    // Fallback: Check product categories if still uncertain
    if (!$has_local_pickup && !$has_shipping) {
        foreach ($order->get_items() as $item) {
            $product = $item->get_product();
            if (!$product) continue;
            
            // Check product categories
            $terms = get_the_terms($product->get_id(), 'product_cat');
            if ($terms && !is_wp_error($terms)) {
                foreach ($terms as $term) {
                    $cat_slug = strtolower($term->slug);
                    $cat_name = strtolower($term->name);
                    
                    if (strpos($cat_slug, 'shipping') !== false || strpos($cat_name, 'shipping') !== false) {
                        $has_shipping = true;
                    }
                    if (strpos($cat_slug, 'pickup') !== false || 
                        strpos($cat_slug, 'local') !== false ||
                        strpos($cat_name, 'pickup') !== false || 
                        strpos($cat_name, 'local') !== false) {
                        $has_local_pickup = true;
                    }
                }
            }
        }
    }
    // ===== FIX ENDS HERE =====
    
    // Determine label based on what was found
    if ($has_shipping && $has_local_pickup) {
        $order_type_label = '[MIXED: SHIPPING + PICKUP]';
    } elseif ($has_local_pickup) {
        $order_type_label = '[LOCAL PICKUP]';
    } elseif ($has_shipping) {
        $order_type_label = '[SHIPPING]';
    }
    
    // Add label to subject if we found a fulfillment method
    if (!empty($order_type_label)) {
        $subject = preg_replace('/^\[.*?\]\s*/', '', $subject);
        $subject = $order_type_label . ' ' . $subject;
    }
    
    return $subject;
}

