// Block checkout if cart contains mixed shipping classes
add_action('woocommerce_check_cart_items', 'lexalarm_prevent_mixed_shipping_classes');
function lexalarm_prevent_mixed_shipping_classes() {
    if (is_admin()) {
        return;
    }
    
    $shipping_classes = array();
    $class_names = array(
        'local_pickup' => 'Local Pickup',
        'local-pickup-only' => 'Local Pickup',
        'ships_nationwide' => 'Nationwide Shipping',
        'ships-nationwide' => 'Nationwide Shipping',
        'Printful' => 'Printful Merchandise'
    );
    
    // Collect all shipping classes in cart
    foreach (WC()->cart->get_cart() as $cart_item) {
        $product = $cart_item['data'];
        $shipping_class = $product->get_shipping_class();
        
        // Skip virtual/donation products (no shipping class)
        if (empty($shipping_class)) {
            continue;
        }
        
        // Normalize class name
        if (!in_array($shipping_class, $shipping_classes)) {
            $shipping_classes[] = $shipping_class;
        }
    }
    
    // If more than one shipping class found, block checkout
    if (count($shipping_classes) > 1) {
        $class_labels = array();
        foreach ($shipping_classes as $class) {
            $label = isset($class_names[$class]) ? $class_names[$class] : ucfirst(str_replace('-', ' ', $class));
            $class_labels[] = '<strong>' . $label . '</strong>';
        }
        
        wc_add_notice(
            sprintf(
                '<div style="background: #fff3cd; border-left: 4px solid #c3202e; padding: 20px; margin: 15px 0;">
                    <strong style="color: #c3202e; font-size: 18px; display: block; margin-bottom: 15px;">⚠️ Cannot Mix Fulfillment Methods</strong>
                    <p style="margin: 10px 0;">Your cart contains items from multiple fulfillment categories:</p>
                    <p style="margin: 15px 0 15px 20px;">%s</p>
                    <p style="margin: 10px 0;"><strong>These cannot be combined in one order.</strong></p>
                    <p style="margin: 10px 0;">Please remove items from one category to complete your checkout.</p>
                </div>',
                implode(' and ', $class_labels)
            ),
            'error'
        );
    }
}

// Also validate when clicking checkout button
add_action('woocommerce_after_checkout_validation', 'lexalarm_validate_checkout_shipping_classes', 10, 2);
function lexalarm_validate_checkout_shipping_classes($data, $errors) {
    $shipping_classes = array();
    
    foreach (WC()->cart->get_cart() as $cart_item) {
        $product = $cart_item['data'];
        $shipping_class = $product->get_shipping_class();
        
        if (empty($shipping_class)) {
            continue;
        }
        
        if (!in_array($shipping_class, $shipping_classes)) {
            $shipping_classes[] = $shipping_class;
        }
    }
    
    if (count($shipping_classes) > 1) {
        $errors->add('mixed_shipping', __('Your cart contains items that require different fulfillment methods. Please complete separate orders.', 'woocommerce'));
    }
}

