<script>
// ============================================================
// CONTENT INJECTED FROM PHP (massport-campaign-content.php)
// Do NOT edit these variables — edit the content file instead.
// ============================================================
var CAMPAIGN_RECIPIENT = <?php echo json_encode($meta['massport_email']); ?>;
var CAMPAIGN_SUBJECT = <?php echo json_encode($meta['email_subject']); ?>;
var CAMPAIGN_SHORT_MAILTO_BODY = <?php echo massport_js_mailto_body($short_mailto_body); ?>;
var CAMPAIGN_LONG_MAILTO_BODY = <?php echo massport_js_mailto_body($long_mailto_body); ?>;
var CAMPAIGN_LONG_PLAIN_TEXT = <?php echo massport_js_plain_text($long_plain_text); ?>;
var CAMPAIGN_WPFORMS_TRACKING_ID = <?php echo json_encode($meta['wpforms_tracking_id']); ?>;

function sendTrackedEmail(actionType) {
    console.log('=== sendTrackedEmail called ===');
    console.log('Action type:', actionType);

    var userName = document.getElementById('user_name_massport').value.trim();
    var userEmail = document.getElementById('user_email_massport').value.trim();

    console.log('User name:', userName);
    console.log('User email:', userEmail);

    if (!userName || !userEmail) {
        alert('Please enter your name and email');
        return;
    }

    // Validate email format
    var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(userEmail)) {
        alert('Please enter a valid email address');
        return;
    }

    console.log('Validation passed, filling hidden form...');

    // Find the hidden WPForms form and fill it
    var nameField = document.querySelector('input[name="wpforms[fields][1]"]');
    var emailField = document.querySelector('input[name="wpforms[fields][2]"]');
    var actionField = document.querySelector('input[name="wpforms[fields][3]"]');

    if (nameField && emailField && actionField) {
        nameField.value = userName;
        emailField.value = userEmail;
        actionField.value = actionType;

        console.log('Hidden form fields populated');

        // Find and click the submit button
        var submitButton = document.querySelector('#wpforms-submit-' + CAMPAIGN_WPFORMS_TRACKING_ID);
        if (submitButton) {
            console.log('Clicking hidden form submit button');
            submitButton.click();
        } else {
            console.error('Submit button not found');
        }
    } else {
        console.error('Hidden form fields not found');
        console.log('Name field:', nameField);
        console.log('Email field:', emailField);
        console.log('Action field:', actionField);
    }

    console.log('Opening email client...');

   // Immediately call email function based on action type
if (actionType === 'short') {
    sendProductionEmail();
} else if (actionType === 'gmail') {
    // Redirect to Gmail helper page with name and email
    var gmailUrl = '<?php echo esc_url( home_url("/massport-gmail-helper/") ); ?>' +
        '?name=' + encodeURIComponent(userName) +
        '&email=' + encodeURIComponent(userEmail);
    window.location.href = gmailUrl;
} else {
    openFullLetterEmail();
}
}

function sendProductionEmail() {
    window.location.href = 'mailto:' + encodeURIComponent(CAMPAIGN_RECIPIENT) +
        '?subject=' + encodeURIComponent(CAMPAIGN_SUBJECT) +
        '&body=' + CAMPAIGN_SHORT_MAILTO_BODY;
}

function openFullLetterEmail() {
    // Copy full letter to clipboard
    if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(CAMPAIGN_LONG_PLAIN_TEXT).catch(function() {
            copyTextFallback(CAMPAIGN_LONG_PLAIN_TEXT);
        });
    } else {
        copyTextFallback(CAMPAIGN_LONG_PLAIN_TEXT);
    }

    // Open email with production recipient
    window.location.href = 'mailto:' + encodeURIComponent(CAMPAIGN_RECIPIENT) +
        '?subject=' + encodeURIComponent(CAMPAIGN_SUBJECT) +
        '&body=' + CAMPAIGN_LONG_MAILTO_BODY;

    alert('Full letter copied to clipboard AND email opened! Paste letter if email body is empty.');
}

// Fallback copy function
function copyTextFallback(text) {
    const textArea = document.createElement('textarea');
    textArea.value = text;
    textArea.style.position = 'fixed';
    textArea.style.opacity = '0';
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();

    try {
        document.execCommand('copy');
    } catch (err) {
        console.error('Copy failed:', err);
    }

    document.body.removeChild(textArea);
}

function handleGmailClick() {
    var userName = document.getElementById('user_name_massport').value.trim();
    var userEmail = document.getElementById('user_email_massport').value.trim();

    if (userName && userEmail) {
        var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(userEmail)) {
            alert('Please enter a valid email address');
            return;
        }

        var nameField = document.querySelector('input[name="wpforms[fields][1]"]');
        var emailField = document.querySelector('input[name="wpforms[fields][2]"]');
        var actionField = document.querySelector('input[name="wpforms[fields][3]"]');

        if (nameField && emailField && actionField) {
            nameField.value = userName;
            emailField.value = userEmail;
            actionField.value = 'gmail';

            var submitButton = document.querySelector('#wpforms-submit-' + CAMPAIGN_WPFORMS_TRACKING_ID);
            if (submitButton) {
                submitButton.click();
            }
        }

        sessionStorage.setItem('gmail_name', userName);
        sessionStorage.setItem('gmail_email', userEmail);
    }

    window.location.href = '<?php echo esc_url( home_url("/massport-gmail-helper/") ); ?>';
}

function requestGovernorPDF() {
    var userName = document.getElementById('user_name_massport').value.trim();
    var userEmail = document.getElementById('user_email_massport').value.trim();

    if (!userName || !userEmail) {
