    }

    var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(userEmail)) {
        alert('Please enter a valid email address.');
        return;
    }

    var button = event.target.closest('button');
    var originalText = button.innerHTML;
    button.innerHTML = 'Sending...';
    button.disabled = true;

    var formData = new FormData();
    formData.append('action', 'generate_governor_pdf');
    formData.append('nonce', '<?php echo wp_create_nonce("governor_pdf_nonce"); ?>');
    formData.append('name', userName);
    formData.append('email', userEmail);

    fetch('<?php echo admin_url("admin-ajax.php"); ?>', {
        method: 'POST',
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            button.innerHTML = 'Sent!';
            alert('Success! Check your email for the Governor Healey letter PDF.');
        } else {
            button.innerHTML = originalText;
            alert('Error: ' + (data.data || 'Failed to generate PDF'));
        }
        button.disabled = false;
    })
    .catch(error => {
        button.innerHTML = originalText;
        button.disabled = false;
        alert('Error sending request. Please try again.');
    });
}
</script>

