function handle_governor_pdf_request() {

    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'governor_pdf_nonce')) {
        wp_send_json_error('Invalid security token');
        exit;
    }

    $user_data = array(
        'name' => isset($_POST['name']) ? sanitize_text_field($_POST['name']) : '',
        'email' => isset($_POST['email']) ? sanitize_email($_POST['email']) : '',
        'street' => isset($_POST['street']) ? sanitize_text_field($_POST['street']) : '',
        'apt' => isset($_POST['apt']) ? sanitize_text_field($_POST['apt']) : '',
        'city' => isset($_POST['city']) ? sanitize_text_field($_POST['city']) : '',
        'zip' => isset($_POST['zip']) ? sanitize_text_field($_POST['zip']) : '',
        'date' => date('F j, Y')
    );

    if (empty($user_data['name']) || empty($user_data['email'])) {
        wp_send_json_error('Name and email are required');
        exit;
    }

    try {
        $generator = new Massport_Governor_PDF_Generator();
        $result = $generator->generate_and_send($user_data);

        if ($result) {
            wp_send_json_success('PDF sent to your email!');
        } else {
            wp_send_json_error('Failed to generate PDF');
        }
    } catch (Exception $e) {
        wp_send_json_error('Error: ' . $e->getMessage());
    }

    exit;
}

