/**
 * Plugin Name: WPForms Entries REST API Endpoint
 * Description: Adds a custom REST API endpoint to access WPForms entries
 * For: Lexington Alarm form data export system
 * 
 * INSTALLATION:
 * 1. Go to WordPress Admin → Snippets → Add New
 * 2. Name: "WPForms Entries API Endpoint"
 * 3. Paste this entire code
 * 4. Set to "Run everywhere"
 * 5. Save and Activate
 *
 * ENDPOINTS CREATED:
 * GET /wp-json/lexalarm/v1/forms/{form_id}/entries - Get all entries for a form
 * DELETE /wp-json/lexalarm/v1/forms/{form_id}/entries/{entry_id} - Delete an entry
 *
 * SECURITY:
 * - Requires WordPress Application Password authentication
 * - User must have 'manage_options' capability (admin only)
 */

// Register the REST API routes
add_action('rest_api_init', function() {
    
    // GET entries for a form
    register_rest_route('lexalarm/v1', '/forms/(?P<form_id>\d+)/entries', array(
        'methods'  => 'GET',
        'callback' => 'lexalarm_get_form_entries',
        'permission_callback' => 'lexalarm_check_permissions',
        'args' => array(
            'form_id' => array(
                'required' => true,
                'type' => 'integer',
                'description' => 'The WPForms form ID',
            ),
        ),
    ));
    
    // DELETE a specific entry
    register_rest_route('lexalarm/v1', '/forms/(?P<form_id>\d+)/entries/(?P<entry_id>\d+)', array(
        'methods'  => 'DELETE',
        'callback' => 'lexalarm_delete_entry',
        'permission_callback' => 'lexalarm_check_permissions',
        'args' => array(
            'form_id' => array(
                'required' => true,
                'type' => 'integer',
            ),
            'entry_id' => array(
                'required' => true,
                'type' => 'integer',
            ),
        ),
    ));
});

/**
 * Permission check - must be authenticated admin
 */
function lexalarm_check_permissions($request) {
    // Must be logged in
    if (!is_user_logged_in()) {
        return new WP_Error(
            'rest_not_logged_in',
            'You must be authenticated to access this endpoint.',
            array('status' => 401)
        );
    }
    
    // Must have admin capabilities
    if (!current_user_can('manage_options')) {
        return new WP_Error(
            'rest_forbidden',
            'You do not have permission to access form entries.',
            array('status' => 403)
        );
    }
    
    return true;
}

/**
 * Get all entries for a form
 */
function lexalarm_get_form_entries($request) {
    $form_id = absint($request['form_id']);
    
    // Check if WPForms is active
    if (!function_exists('wpforms')) {
        return new WP_Error(
            'wpforms_not_active',
            'WPForms is not active on this site.',
            array('status' => 500)
        );
    }
    
    // Get entries from database
    global $wpdb;
    $table_name = $wpdb->prefix . 'wpforms_entries';
    
    // Check if table exists
    if ($wpdb->get_var("SHOW TABLES LIKE '$table_name'") !== $table_name) {
        return new WP_Error(
            'table_not_found',
            'WPForms entries table not found. Make sure WPForms Pro is installed.',
            array('status' => 500)
        );
    }
    
    // Query entries
    $entries = $wpdb->get_results(
        $wpdb->prepare(
            "SELECT * FROM $table_name WHERE form_id = %d ORDER BY date DESC",
            $form_id
        ),
        ARRAY_A
    );
    
    if (empty($entries)) {
        return array(); // Return empty array, not error
    }
    
    // Format entries for response
    $formatted_entries = array();
    foreach ($entries as $entry) {
        $fields = json_decode($entry['fields'], true);
        
        $formatted_entries[] = array(
            'entry_id' => $entry['entry_id'],
            'form_id' => $entry['form_id'],
            'date_created' => $entry['date'],
            'date_modified' => isset($entry['date_modified']) ? $entry['date_modified'] : $entry['date'],
            'status' => isset($entry['status']) ? $entry['status'] : 'published',
            'user_id' => isset($entry['user_id']) ? $entry['user_id'] : 0,
            'user_ip' => isset($entry['ip_address']) ? $entry['ip_address'] : '',
            'user_agent' => isset($entry['user_agent']) ? $entry['user_agent'] : '',
            'fields' => $fields,
        );
    }
    
    return $formatted_entries;
}

/**
 * Delete a specific entry
 */
function lexalarm_delete_entry($request) {
    $form_id = absint($request['form_id']);
    $entry_id = absint($request['entry_id']);
    
    global $wpdb;
    $table_name = $wpdb->prefix . 'wpforms_entries';
    
    // Verify entry exists and belongs to the specified form
    $entry = $wpdb->get_row(
        $wpdb->prepare(
            "SELECT entry_id FROM $table_name WHERE entry_id = %d AND form_id = %d",
            $entry_id,
            $form_id
        )
    );
    
    if (!$entry) {
        return new WP_Error(
            'entry_not_found',
            'Entry not found or does not belong to this form.',
            array('status' => 404)
        );
    }
    
    // Delete the entry
    $deleted = $wpdb->delete(
        $table_name,
        array(
            'entry_id' => $entry_id,
            'form_id' => $form_id,
        ),
        array('%d', '%d')
    );
    
    if ($deleted === false) {
        return new WP_Error(
            'delete_failed',
            'Failed to delete entry.',
            array('status' => 500)
        );
    }
    
    // Also delete entry meta if table exists
    $meta_table = $wpdb->prefix . 'wpforms_entry_meta';
    if ($wpdb->get_var("SHOW TABLES LIKE '$meta_table'") === $meta_table) {
        $wpdb->delete(
            $meta_table,
            array('entry_id' => $entry_id),
            array('%d')
        );
    }
    
    return array(
        'deleted' => true,
        'entry_id' => $entry_id,
        'form_id' => $form_id,
    );
}

/**
 * Local Pickup Handler for Lexington Alarm
 * Handles checkout fields, notices, and admin email checklists
 * Supports: Virtual products, Local pickup, Shipped items
 */

// Remove shipping fields when local pickup is the only option
add_filter('woocommerce_checkout_fields', 'remove_shipping_for_local_pickup_only');
function remove_shipping_for_local_pickup_only($fields) {
    $available_methods = WC()->shipping()->get_packages();
    
    $only_local_pickup = true;
    if (!empty($available_methods) && !empty($available_methods[0]['rates'])) {
        foreach ($available_methods[0]['rates'] as $rate) {
            if ($rate->method_id !== 'local_pickup') {
                $only_local_pickup = false;
                break;
            }
        }
    }
    
    if ($only_local_pickup) {
        unset($fields['shipping']);
    }
    
    return $fields;
}

// Determine if cart needs shipping (skip virtual products)
add_filter('woocommerce_cart_needs_shipping', 'disable_shipping_for_pickup_and_virtual');
function disable_shipping_for_pickup_and_virtual($needs_shipping) {
    foreach (WC()->cart->get_cart() as $cart_item) {
        $product = $cart_item['data'];
        
        // Skip virtual products - they never need shipping
        if ($product->is_virtual()) {
            continue;
        }
        
        // Physical product - check shipping class
        $shipping_class = $product->get_shipping_class();
        
        // If NOT local pickup, shipping is needed
        if ($shipping_class !== 'local_pickup') {
            return true;
        }
    }
    
    // All products are virtual or local pickup
    return false;
}

// Determine if cart needs shipping address (skip virtual products)
add_filter('woocommerce_cart_needs_shipping_address', 'disable_shipping_address_for_virtual_and_pickup', 99);
function disable_shipping_address_for_virtual_and_pickup($needs_address) {
    foreach (WC()->cart->get_cart() as $cart_item) {
        $product = $cart_item['data'];
        
        // Skip virtual products
        if ($product->is_virtual()) {
            continue;
        }
        
        // Physical product - check shipping class
        $shipping_class = $product->get_shipping_class();
        
        // If NOT local pickup, address is needed
        if ($shipping_class !== 'local_pickup') {
            return true;
        }
    }
    
    return false;
}

// Simplify billing fields for virtual/pickup orders
add_filter('woocommerce_billing_fields', 'simplify_billing_for_local_pickup', 20);
function simplify_billing_for_local_pickup($fields) {
    if (!WC()->cart->needs_shipping()) {
        if (isset($fields['billing_address_1'])) {
            $fields['billing_address_1']['required'] = false;
        }
        if (isset($fields['billing_postcode'])) {
            $fields['billing_postcode']['required'] = false;
        }
        if (isset($fields['billing_state'])) {
            $fields['billing_state']['required'] = false;
        }
        if (isset($fields['billing_city'])) {
            $fields['billing_city']['label'] = 'Your Town';
            $fields['billing_city']['placeholder'] = 'e.g., Lexington, Arlington';
        }
    }
    
    return $fields;
}

