/**
 * Cart Page Donation Add-On
 * Shows donation options when cart has physical products (not just donations)
 */

// Add donation section to cart page
add_action('woocommerce_before_cart_totals', 'lexalarm_cart_donation_addon');
function lexalarm_cart_donation_addon() {
    
    // Donation product ID
    $donation_product_id = 596;
    
    // Check if cart has non-donation products
    $has_physical_products = false;
    $donation_in_cart = false;
    
    foreach (WC()->cart->get_cart() as $cart_item) {
        $product = $cart_item['data'];
        $product_id = $cart_item['product_id'];
        
        // Check if this is the donation product
        if ($product_id == $donation_product_id) {
            $donation_in_cart = true;
        } else {
            $has_physical_products = true;
        }
    }
    
    // Don't show if cart only has donations or is empty of physical products
    if (!$has_physical_products) {
        return;
    }
    
    // Get donation product
    $product = wc_get_product($donation_product_id);
    if (!$product || !$product->is_type('variable')) {
        return;
    }
    
    $variations = $product->get_available_variations();
    ?>
    
    <div class="lexalarm-cart-donation" style="background: linear-gradient(135deg, #f0f8ff 0%, #fff 100%); border: 2px solid #044f9d; border-radius: 8px; padding: 20px; margin-bottom: 20px;">
        <h3 style="color: #c3202e; margin: 0 0 10px 0; font-size: 18px;">
            💙 Add a Donation to Your Order
        </h3>
        <p style="margin: 0 0 15px 0; color: #333; font-size: 14px;">
            Support Lexington Alarm's mission to defend democracy and constitutional rights.
        </p>
        
        <?php if ($donation_in_cart): ?>
            <p style="color: #044f9d; font-weight: bold; margin: 0;">
                ✓ Thank you! Donation added to your order.
            </p>
        <?php else: ?>
            <div class="donation-buttons" style="display: flex; gap: 10px; flex-wrap: wrap;">
                <?php
                $amounts = array(5, 10, 25);
                foreach ($variations as $variation) {
                    $variation_obj = wc_get_product($variation['variation_id']);
                    $price = $variation_obj->get_price();
                    
                    if (in_array((int)$price, $amounts)) {
                        $add_url = add_query_arg(array(
                            'add-to-cart' => $donation_product_id,
                            'variation_id' => $variation['variation_id'],
                            'attribute_pa_donation-amount' => $variation_obj->get_attribute('pa_donation-amount')
                        ), wc_get_cart_url());
                        ?>
                        <a href="<?php echo esc_url($add_url); ?>" 
                           class="donation-add-btn" 
                           style="background: #044f9d; color: white; border: none; padding: 10px 20px; border-radius: 5px; cursor: pointer; font-size: 16px; font-weight: bold; text-decoration: none; display: inline-block;">
                            +$<?php echo (int)$price; ?>
                        </a>
                        <?php
                    }
                }
                ?>
            </div>
            <p style="margin: 10px 0 0 0; font-size: 12px; color: #666;">
                <a href="<?php echo get_permalink($donation_product_id); ?>" style="color: #044f9d;">
                    Other amount →
                </a>
            </p>
        <?php endif; ?>
    </div>
    
    <style>
    .donation-add-btn:hover {
        background: #c3202e !important;
        color: white !important;
    }
    </style>
    <?php
}

