    private function add_letter_page($pdf, $user_data, $full_address, $city_state_zip, $member) {
        
        $pdf->SetFont('helvetica', '', 10);
        
        // Sender info
        $pdf->MultiCell(0, 0.2, $user_data['name'], 0, 'L');
