        return;
    }

    document.getElementById('display-name').textContent = userName;
    document.getElementById('display-email').textContent = userEmail;

    var nameField = document.querySelector('input[name="wpforms[fields][1]"]');
    var emailField = document.querySelector('input[name="wpforms[fields][2]"]');
    var actionField = document.querySelector('input[name="wpforms[fields][3]"]');

    if (nameField && emailField && actionField) {
        nameField.value = userName;
        emailField.value = userEmail;
        actionField.value = 'gmail';

        var submitButton = document.querySelector('#wpforms-submit-<?php echo esc_js($meta['wpforms_tracking_id']); ?>');
        if (submitButton) {
            submitButton.click();
        }
    }

    document.getElementById('gmail-form-section').style.display = 'none';
    document.getElementById('gmail-content-wrapper').classList.add('visible');
    document.getElementById('gmail-content-wrapper').scrollIntoView({ behavior: 'smooth' });
}

function gmailCopy(elementId, button) {
    var element = document.getElementById(elementId);
    var text = element.innerText || element.textContent;

    navigator.clipboard.writeText(text).then(function() {
        var originalText = button.innerText;
        button.innerText = 'Copied!';
        button.classList.add('copied');
        setTimeout(function() {
            button.innerText = originalText;
            button.classList.remove('copied');
        }, 2000);
    }).catch(function() {
        var textArea = document.createElement('textarea');
        textArea.value = text;
        document.body.appendChild(textArea);
        textArea.select();
        document.execCommand('copy');
        document.body.removeChild(textArea);
        var originalText = button.innerText;
        button.innerText = 'Copied!';
        button.classList.add('copied');
        setTimeout(function() {
            button.innerText = originalText;
            button.classList.remove('copied');
        }, 2000);
    });
}

function gmailShowLetter(type, clickedTab) {
    document.querySelectorAll('.gmail-tab').forEach(function(tab) {
        tab.classList.remove('active');
    });
    clickedTab.classList.add('active');
    document.querySelectorAll('.gmail-letter').forEach(function(letter) {
        letter.classList.remove('active');
    });
    document.getElementById('gmail-letter-' + type).classList.add('active');
}

