function lexalarm_convert_yt_embeds($content) {
    $pattern = '/<iframe[^>]*src=["\']https?:\/\/(www\.)?(youtube\.com\/embed\/|youtube-nocookie\.com\/embed\/)([a-zA-Z0-9_-]+)[^"\']*["\'][^>]*>[\s]*<\/iframe>/is';
    
    $content = preg_replace_callback($pattern, function($matches) {
        $video_id = $matches[3];
        return do_shortcode('[youtube_lite id="' . $video_id . '"]');
