    return $content;
}

add_shortcode('upcoming_events', 'lexalarm_events_shortcode');

function lexalarm_events_shortcode($atts) {
    $atts = shortcode_atts(array(
        'count' => 3,
        'cache_hours' => 2,
        'calendar' => 'lexingtonalarm',
        'tag' => ''
    ), $atts);
    
    $count = intval($atts['count']);
    $cache_hours = intval($atts['cache_hours']);
    $calendar = sanitize_text_field($atts['calendar']);
    $tag_filter = sanitize_text_field($atts['tag']);
    
    // Check cache first
    $cache_key = 'lexalarm_events_' . $calendar . '_' . sanitize_key($tag_filter);
    $events = get_transient($cache_key);
    
    if ($events === false) {
        // Fetch the Tockify calendar page
        $page_url = 'https://tockify.com/' . $calendar;
        
        $response = wp_remote_get($page_url, array(
            'timeout' => 15,
            'sslverify' => true,
            'user-agent' => 'Mozilla/5.0 (compatible; WordPress)'
        ));
        
        if (is_wp_error($response)) {
            error_log('Upcoming Events: Page fetch error - ' . $response->get_error_message());
            return '<p style="text-align: center; color: #666;">Unable to load events. <a href="/events">View all events</a></p>';
        }
        
        $body = wp_remote_retrieve_body($response);
        
        // Extract JSON-LD schema data
        if (!preg_match('/<script type="application\/ld\+json">\s*(\[.*?\])\s*<\/script>/s', $body, $matches)) {
            error_log('Upcoming Events: Could not find JSON-LD data');
            return '<p style="text-align: center; color: #666;">Unable to load events. <a href="/events">View all events</a></p>';
        }
        
        $json_data = json_decode($matches[1], true);
        
        if (empty($json_data)) {
            return '<p style="text-align: center; color: #666;">No upcoming events found. <a href="/events">View calendar</a></p>';
        }
        
        $events = array();
        $now = current_time('timestamp');
        
        foreach ($json_data as $event_data) {
            if (!isset($event_data['@type']) || $event_data['@type'] !== 'Event') {
                continue;
            }
            
            $start_date = isset($event_data['startDate']) ? strtotime($event_data['startDate']) : 0;
            
            // Only include future events
            if ($start_date < $now) {
                continue;
            }
            
            $title = isset($event_data['name']) ? $event_data['name'] : 'Untitled Event';
            $link = isset($event_data['url']) ? $event_data['url'] : '/events';
            
            $place = '';
            if (isset($event_data['location']['name'])) {
                $place = $event_data['location']['name'];
            }
            
            $events[] = array(
                'title' => $title,
                'date' => $start_date,
                'time' => wp_date('g:i A', $start_date),
                'place' => $place,
                'link' => $link,
                'all_day' => false
            );
        }
        
        // Sort by date
        usort($events, function($a, $b) {
            return $a['date'] - $b['date'];
        });
        
        // Cache for specified hours
        set_transient($cache_key, $events, $cache_hours * HOUR_IN_SECONDS);
    }
    
    // Limit to requested count
    $events = array_slice($events, 0, $count);
    
    if (empty($events)) {
        return '<p style="text-align: center; color: #666;">No upcoming events scheduled. <a href="/events">View calendar</a></p>';
    }
    
    // Build output
    $output = '<div class="lexalarm-upcoming-events">';
    
    foreach ($events as $event) {
        $output .= '<div class="lexalarm-event-card">';
        $output .= '<div class="lexalarm-event-date">';
        $output .= '<span class="lexalarm-event-month">' . esc_html(wp_date('M', $event['date'])) . '</span>';
        $output .= '<span class="lexalarm-event-day">' . esc_html(wp_date('j', $event['date'])) . '</span>';
        $output .= '</div>';
        $output .= '<div class="lexalarm-event-details">';
        $output .= '<h3 class="lexalarm-event-title"><a href="' . esc_url($event['link']) . '" target="_blank">' . esc_html($event['title']) . '</a></h3>';
        $output .= '<p class="lexalarm-event-meta">' . esc_html(wp_date('l', $event['date']));
        if (!empty($event['time'])) {
            $output .= ' &bull; ' . esc_html($event['time']);
        }
        if (!empty($event['place'])) {
            $output .= '<br><span class="lexalarm-event-place">' . esc_html($event['place']) . '</span>';
        }
        $output .= '</p>';
        $output .= '</div>';
        $output .= '</div>';
    }
    
    $output .= '</div>';
    
    return $output;
}

