// Defer non-critical JavaScript
add_filter('script_loader_tag', 'la_defer_scripts', 10, 3);

function la_defer_scripts($tag, $handle, $src) {
    if (is_admin()) {
        return $tag;
    }
    
    $no_defer = array('jquery-core', 'jquery');
    if (in_array($handle, $no_defer)) {
        return $tag;
    }
    
    $defer_scripts = array(
        'woocommerce',
        'wc-add-to-cart',
        'wc-cart-fragments',
        'sourcebuster-js',
        'wc-order-attribution',
    );
    
    if (in_array($handle, $defer_scripts)) {
        if (strpos($tag, 'defer') === false) {
            $tag = str_replace(' src=', ' defer src=', $tag);
        }
    }
    
    return $tag;
}

