add_action('wp_enqueue_scripts', 'la_conditional_woocommerce_assets', 99);

function la_conditional_woocommerce_assets() {
    if (!class_exists('WooCommerce')) {
        return;
    }
    
    // Pages where WooCommerce should fully load
    $woo_pages = array(
        'shop',
        'cart',
        'checkout',
        'my-account',
        'order-signs',
        'store',
    );
    
    $needs_woo = false;
    
    // WooCommerce native pages
    if (is_woocommerce() || is_cart() || is_checkout() || is_account_page()) {
        $needs_woo = true;
    }
    
    // Specific page slugs
    if (is_page($woo_pages)) {
        $needs_woo = true;
    }
    
    // Single products
    if (is_product() || is_product_category() || is_product_tag()) {
        $needs_woo = true;
    }
    
    // Check for WooCommerce shortcodes
    global $post;
    if (is_a($post, 'WP_Post')) {
        $woo_shortcodes = array(
            '[products', '[product_page', '[product_category',
            '[add_to_cart', '[woocommerce_cart', '[woocommerce_checkout',
            '[woocommerce_my_account', '[recent_products', '[featured_products',
            '[sale_products', '[best_selling_products', '[top_rated_products'
        );
        foreach ($woo_shortcodes as $shortcode) {
            if (strpos($post->post_content, $shortcode) !== false) {
                $needs_woo = true;
                break;
            }
        }
    }
    
    // Remove assets if not needed
    if (!$needs_woo) {
        // CSS
        wp_dequeue_style('woocommerce-general');
        wp_dequeue_style('woocommerce-layout');
        wp_dequeue_style('woocommerce-smallscreen');
        wp_dequeue_style('wc-blocks-style');
        wp_dequeue_style('wc-blocks-vendors-style');
        
        // JS
        wp_dequeue_script('woocommerce');
        wp_dequeue_script('wc-add-to-cart');
        wp_dequeue_script('wc-cart-fragments');
        wp_dequeue_script('wc-add-to-cart-variation');
        wp_dequeue_script('wc-single-product');
        wp_dequeue_script('jquery-blockui');
        wp_dequeue_script('js-cookie');
        
        // Product Addons
        wp_dequeue_script('woocommerce-addons');
        wp_dequeue_script('pao-validation');
        wp_dequeue_style('woocommerce-addons-css');
        
        // Stripe
        wp_dequeue_script('wc-stripe');
        wp_dequeue_script('stripe');
        
        // Order attribution
        wp_dequeue_script('sourcebuster-js');
        wp_dequeue_script('wc-order-attribution');
    }
}

