    $tockify_pages = array(
        'events',
        'calendar',
    );
    
    // Check if we're on a Tockify-enabled page
    $should_load = false;
    
    if (is_page($tockify_pages)) {
        $should_load = true;
    }
    
    // Also check for Tockify content in the page
    global $post;
    if (is_a($post, 'WP_Post')) {
        if (strpos($post->post_content, 'data-tockify') !== false ||
            strpos($post->post_content, 'tockify') !== false) {
            $should_load = true;
        }
    }
    
    // If Tockify shouldn't load, block the script
    if (!$should_load) {
        add_action('wp_enqueue_scripts', function() {
            wp_dequeue_script('tockify-embed');
            wp_deregister_script('tockify-embed');
        }, 100);
        
        add_filter('script_loader_src', function($src) {
            if (strpos($src, 'tockify.com') !== false) {
                return false;
            }
            return $src;
        });
        
        ?>
        <script>
        window.tockify = { blocked: true };
        </script>
        <?php
    }
}

